$$\begin{array}{l}
  {{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{f\left( {x + h} \right) - f(x)}{h}}} \\
  {\phantom{f^{\prime}(x)} = {\lim\limits_{h\rightarrow 0}\frac{e^{x + h} - e^{x}}{h}}} \\
  {\phantom{f^{\prime}(x)} = \lim\limits_{h\rightarrow 0}\frac{e^{x}\left( {e^{h} - 1} \right)}{h}\qquad{\text{Write}e^{x + h} = e^{x}e^{h}\text{and factor}.}} \\
  {\phantom{f^{\prime}(x)} = {e^{x}\lim\limits_{h\rightarrow 0}\frac{e^{h} - 1}{h}}\qquad\text{Why?}}
  \end{array}$$

$$\begin{array}{l}
  {\frac{\mathit{dy}}{\mathit{dx}}{= x\frac{d}{\mathit{dx}}{(e^{- 2x})} + e^{- 2x}\frac{d}{\mathit{dx}}(x)}} \\
  {\phantom{\frac{\mathit{dy}}{\mathit{dx}}}{= xe^{- 2x}\frac{d}{\mathit{dx}}\left( {- 2x} \right) + e^{- 2x}}\qquad{\text{Use the Chain Rule on the first term}.}} \\
  {\phantom{\frac{\mathit{dy}}{\mathit{dx}}}{= - 2xe^{- 2x} + e^{- 2x}}} \\
  {\phantom{\frac{\mathit{dy}}{\mathit{dx}}}{= e^{- 2x}\left( {1 - 2x} \right)}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{\prime}(x)}{= x\frac{d}{\mathit{dx}}\left( e^{- x} \right) + e^{- x}\frac{d}{\mathit{dx}}(x)}} \\
  {\phantom{f^{\prime}(x)}{= - xe^{- x} + e^{- x} = \left( {1 - x} \right)e^{- x}}}
  \end{array}$$

$$\begin{array}{l}
  {{f^{''}(x)}{= \left( {1 - x} \right)\frac{d}{\mathit{dx}}\left( e^{- x} \right) + e^{- x}\frac{d}{\mathit{dx}}\left( {1 - x} \right)}} \\
  {\phantom{f^{''}(x)}{= \left( {1 - x} \right)\left( {- e^{- x}} \right) + e^{- x}\left( {- 1} \right)}} \\
  {\phantom{f^{''}(x)}{= - e^{- x} + xe^{- x} - e^{- x} = \left( {x - 2} \right)e^{- x}}}
  \end{array}$$
